      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-alt: #f8fafc;
      --text: #0f172a;
      --muted: #475569;
      --border: #dbe4f0;
      --accent: #2563eb;
      --accent-soft: #dbeafe;
      --success: #16a34a;
      --shadow: 0 20px 50px rgba(15, 23, 42, 0.08);
      --radius: 18px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #e0ecff 0%, transparent 35%),
        var(--bg);
      color: var(--text);
      line-height: 1.5;
      min-height: 100vh;
    }

    .page {
      max-width: 880px;
      margin: 0 auto;
      padding: 40px 20px 56px;
    }

    .hero {
      background: linear-gradient(135deg, #0f172a, #1d4ed8);
      color: #fff;
      border-radius: 28px;
      padding: 32px;
      box-shadow: var(--shadow);
      margin-bottom: 24px;
    }

    .hero h1 {
      margin: 0 0 10px;
      font-size: clamp(1.8rem, 3vw, 2.6rem);
      line-height: 1.1;
    }

    .hero p {
      margin: 0;
      max-width: 60ch;
      color: rgba(255, 255, 255, 0.86);
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 22px;
      box-shadow: var(--shadow);
    }

    .question-title {
      margin: 0 0 8px;
      font-size: 1.1rem;
    }

    .help-text {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .options {
      display: grid;
      gap: 10px;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .option {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      background: var(--surface-alt);
      border: 1px solid var(--border);
      border-radius: 14px;
      transition: border-color 0.2s ease, transform 0.2s ease, background 0.2s ease;
    }

    .option:hover {
      border-color: #b8cdfc;
      background: #eff6ff;
      transform: translateY(-1px);
    }

    .option input {
      margin-top: 3px;
      width: 18px;
      height: 18px;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .option label {
      cursor: pointer;
      flex: 1;
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 14px;
      flex-wrap: wrap;
      padding-top: 6px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      background: var(--accent);
      color: #fff;
      font-weight: 700;
      padding: 14px 22px;
      font-size: 1rem;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
      transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
    }

    button:hover {
      background: #1d4ed8;
      transform: translateY(-1px);
    }

    button:focus-visible,
    input:focus-visible {
      outline: 3px solid var(--accent-soft);
      outline-offset: 3px;
    }

    #result {
      margin: 0;
      color: var(--success);
      font-weight: 600;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 640px) {
      .page {
        padding: 18px 14px 40px;
      }

      .hero,
      .form-field {
        padding: 20px;
        border-radius: 22px;
      }
    }
  </style>
